def audit_disjoint(old_pools,new_pools=None):
    """-> (ok, lines): sizes, duplicates inside a pool, exact-string overlap with the old pools (must be 0), shared words (information: function words and the slots are expected to repeat), and a compose() smoke test"""
    new=new_pools or HOLD_POOLS;ok=True;L=[]
    for k,n in SIZES.items():
        v=new[k];o=old_pools[k];ex=sorted(set(v)&set(o));wd=sorted({w.strip('.,').lower() for s in v for w in s.split()}&{w.strip('.,').lower() for s in o for w in s.split()}-{'the','of','a','in','at','and','who','that','as','by','to','from'}-{'{x}','{p}','{o}','{a_o}',"{p}'s","{o}'s"})
        ok&=len(v)==n and len(set(v))==len(v) and not ex;L.append(f'{k}: {len(v)} (need {n}), duplicates {len(v)-len(set(v))}, exact overlap with old {len(ex)} {ex}, shared content words with old {len(wd)} {wd[:12]}')
    return ok,L
